using System;
using System.Collections.Generic;
using System.IO;
using MassiveArmy.Planetary;
using UnityEngine;
namespace MassiveArmy.EditorTools
{
    public static class PlanetTerrainFlightValidation
    {
        [Serializable]sealed class Report{public string status="PASS",error="";public List<string> checks=new List<string>();public float maximumHeightError;}
        public static void Run(){var report=new Report();Directory.CreateDirectory("TestResults/Planetary/TerrainFlight");var d=ScriptableObject.CreateInstance<PlanetDefinition>();d.radius=6000;d.terrainHeight=240;d.oceanHeight=-35;var shader=UnityEngine.Object.Instantiate(Resources.Load<ComputeShader>("MassiveArmy/PlanetTerrainValidation"));
            void Check(bool valid,string text){if(!valid)throw new InvalidOperationException(text);report.checks.Add(text);}
            try{var surface=new PlanetSurface(d);var a=new Vector3(1,.12f,1.3f).normalized;d.Edits.PrepareStartingAreas(a,-a);Check(Mathf.Abs(surface.SampleHeight(a)-surface.SampleHeight((a+Vector3.up*.005f).normalized))<.01f,"Starting plateaus retain level construction ground");
                PlanetDevelopment.BindSurface(shader,d);float original=surface.SampleHeight(Vector3.up);Check(d.Edits.AddCrater(Vector3.up,120),"A canonical crater can be added after GPU consumers bind");Check(Mathf.Abs(surface.SampleHeight(Vector3.up)-original+19.2f)<.001f,"Crater centre deforms terrain by the expected 19.2 metres");
                var seam=new Vector3(1,1,0).normalized;Check(d.Edits.AddCrater(seam,150),"Crater can cross a cube-face seam");Check(d.Edits.AddCrater(Vector3.down,90),"Crater can cross a pole");
                var directions=new Vector4[2048];for(int i=0;i<directions.Length;i++){float z=1-2*(i+.5f)/directions.Length,angle=i*2.39996323f,r=Mathf.Sqrt(1-z*z);var v=new Vector3(r*Mathf.Cos(angle),z,r*Mathf.Sin(angle));if(i<512)v=(seam+new Vector3(Mathf.Sin(i)*.03f,Mathf.Cos(i)*.03f,Mathf.Sin(i*.7f)*.03f)).normalized;else if(i<1024)v=(Vector3.up+new Vector3(Mathf.Sin(i)*.03f,0,Mathf.Cos(i)*.03f)).normalized;directions[i]=v;}
                using(var input=new GraphicsBuffer(GraphicsBuffer.Target.Structured,directions.Length,16))using(var output=new GraphicsBuffer(GraphicsBuffer.Target.Structured,directions.Length,16)){int kernel=shader.FindKernel("Sample");input.SetData(directions);shader.SetBuffer(kernel,"_Directions",input);shader.SetBuffer(kernel,"_Samples",output);shader.SetInt("_SampleCount",directions.Length);shader.Dispatch(kernel,directions.Length/128,1,1);var values=new Vector4[directions.Length];output.GetData(values);for(int i=0;i<values.Length;i++)report.maximumHeightError=Mathf.Max(report.maximumHeightError,Mathf.Abs(values[i].x-surface.SampleHeight((Vector3)directions[i])));Check(report.maximumHeightError<.005f,"CPU/GPU terrain edits agree within 5 mm around seams, poles, rims and plateaus");
                    var single=ScriptableObject.CreateInstance<PlanetDefinition>();single.radius=6000;single.terrainHeight=240;single.oceanHeight=-35;
                    try{for(int i=0;i<directions.Length;i++){float sampleAngle=i*2.39996323f,r=(i%128)/127f*.03f;directions[i]=new Vector3(r*Mathf.Cos(sampleAngle),1,r*Mathf.Sin(sampleAngle)).normalized;}input.SetData(directions);PlanetDevelopment.BindSurface(shader,single);shader.Dispatch(kernel,directions.Length/128,1,1);output.GetData(values);float emptyError=0;for(int i=0;i<values.Length;i++)emptyError=Mathf.Max(emptyError,Mathf.Abs(values[i].x-PlanetTerrainEdits.BaseHeight(single,(Vector3)directions[i])));Check(emptyError<.005f,"Unedited specialized height shader agrees with CPU terrain");
                        single.Edits.AddCrater(Vector3.up,120);shader.Dispatch(kernel,directions.Length/128,1,1);output.GetData(values);float singleError=0;for(int i=0;i<values.Length;i++)singleError=Mathf.Max(singleError,Mathf.Abs(values[i].x-single.Edits.Height((Vector3)directions[i])));report.maximumHeightError=Mathf.Max(report.maximumHeightError,singleError);Check(singleError<.005f,"First crater switches the already-bound single-crater shader and agrees across its bowl and rim");
                    }finally{UnityEngine.Object.DestroyImmediate(single);}
}
                float crater=surface.SampleHeight(Vector3.up);Check(surface.Raycast(new Ray(Vector3.up*(d.radius+500),Vector3.down),out var hit)&&Mathf.Abs(hit.magnitude-d.radius-crater)<.01f,"Terrain picking intersects the deformed crater floor");
                Check(d.ReliefBound>=d.terrainHeight+24,"Geometry bounds include crater displacement");
                int count=d.Edits.Count;d.Edits.AddCrater(Vector3.up,120);Check(d.Edits.Count==count,"Repeated impacts merge instead of consuming unbounded crater records");
                for(int i=0;i<80;i++){float z=1-2*(i+.5f)/80,angle=i*2.39996323f,r=Mathf.Sqrt(1-z*z);d.Edits.AddCrater(new Vector3(r*Mathf.Cos(angle),z,r*Mathf.Sin(angle)),20);}Check(d.Edits.Count==PlanetTerrainEdits.Capacity,"Crater storage stays at its fixed 32-record budget");Check(Mathf.Abs(surface.SampleHeight(Vector3.up)-crater)<.001f,"Reaching the budget does not erase an existing crater");
                using(var input=new GraphicsBuffer(GraphicsBuffer.Target.Structured,directions.Length,16))using(var output=new GraphicsBuffer(GraphicsBuffer.Target.Structured,directions.Length,16)){for(int i=0;i<directions.Length;i++){int site=i%80;float sampleZ=1-2*(site+.5f)/80,sampleAngle=site*2.39996323f,sampleR=Mathf.Sqrt(1-sampleZ*sampleZ);var center=new Vector3(sampleR*Mathf.Cos(sampleAngle),sampleZ,sampleR*Mathf.Sin(sampleAngle));var tangent=Vector3.Cross(Mathf.Abs(center.y)>.9f?Vector3.right:Vector3.up,center).normalized;directions[i]=(center+tangent*(i/80%5*.001f)).normalized;}int kernel=shader.FindKernel("Sample");input.SetData(directions);shader.SetBuffer(kernel,"_Directions",input);shader.SetBuffer(kernel,"_Samples",output);shader.Dispatch(kernel,directions.Length/128,1,1);var values=new Vector4[directions.Length];output.GetData(values);float fullError=0;for(int i=0;i<values.Length;i++)fullError=Mathf.Max(fullError,Mathf.Abs(values[i].x-surface.SampleHeight((Vector3)directions[i])));report.maximumHeightError=Mathf.Max(report.maximumHeightError,fullError);Check(fullError<.005f,"Full 32-crater constant buffer, including the highest mask bit, matches CPU bowls and rims");}

            }catch(Exception e){report.status="FAIL";report.error=e.ToString();throw;}finally{UnityEngine.Object.DestroyImmediate(shader);UnityEngine.Object.DestroyImmediate(d);File.WriteAllText("TestResults/Planetary/TerrainFlight/math.json",JsonUtility.ToJson(report,true));}}
    }
}

